import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/7/","title":"第 7 课 · 动词 Verbs | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 7 课 · 动词 Verbs","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/7/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第七课 语法专题 · 第七课 对应前置讲义 P17–19 + 教材上册 P41–54 · 情态动词表猜测三张表为考试重点。 考点地图 · 点击跳转 分类总口诀：情 义 助 你 系 鞋 带 → 情态动词、实义动词、助动词、系动词 动词的概念：表示动作或状态的...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 7 课 · 动词 Verbs\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/7/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 7 课 · 动词 Verbs"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第七课 语法专题 · 第七课 对应前置讲义 P17–19 + 教材上册 P41–54 · 情态动词表猜测三张表为考试重点。 考点地图 · 点击跳转 分类总口诀：情 义 助 你 系 鞋 带 → 情态动词、实义动词、助动词、系动词 动词的概念：表示动作或状态的..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 7 课 · 动词 Verbs"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/7/"}]]},"readingTime":{"minutes":48.53,"words":14558},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/7.md","headers":[]}`),u={name:`7.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0007-verbs.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第七课`,-1)]),l[10]||=r(`<p>语法专题 · 第七课</p><p>对应前置讲义 P17–19 + 教材上册 P41–54 · 情态动词表猜测三张表为考试重点。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>分类总口诀</strong>：情 义 助 你 系 鞋 带 → 情态动词、实义动词、助动词、系动词</a></li><li><a href="#pt-1"><strong>动词的概念</strong>：表示动作或状态的词</a></li><li><a href="#pt-2"><strong>实义动词</strong>：vi./vt.、双宾语（to/for）、复合宾语（宾补 6 种形式）</a></li><li><a href="#pt-3"><strong>系动词</strong>：五感、五变、三保持、两结果、一是、一像</a></li><li><a href="#pt-4"><strong>助动词</strong>：do、have、be、will 四大帮手</a></li><li><a href="#pt-5"><strong>情态动词</strong>：用法口诀 + 表猜测三张表（考试重点）</a></li></ol></div><h2 id="第一部分-·-动词的概念-前置讲义-p17" tabindex="-1"><a class="header-anchor" href="#第一部分-·-动词的概念-前置讲义-p17"><span>第一部分 · 动词的概念（前置讲义 P17）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一部分 · 动词的概念（前置讲义 P17）</p><ul><li><strong>目标</strong>：解决“这个动词是哪一类”：用“情 义 助 你 系 鞋 带”识别情态动词、实义动词、助动词、系动词，为后面选对句型打底。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>动词的概念与分类总口诀</code></li></ul></div><h3 id="第一部分-·-动词的概念-前置讲义-p17-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一部分-·-动词的概念-前置讲义-p17-·-小步学"><span>第一部分 · 动词的概念（前置讲义 P17） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 0 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>动词：说出动作或状态</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>情 义 助 你 系 鞋 带：先认清动词的身份</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：说出动词的四类名称，并各举一句自己造的例句；再用一句话说明为什么“一个句子只有一个谓语动词”是判断句型的第一步。</p><div class="hint-container tip"><p class="hint-container-title">情 义 助 你 系 鞋 带：先认清动词的身份</p><p><strong>句意</strong>：She runs every morning. 意思是“她每天早上跑步”；She is a doctor. 意思是“她是一名医生”。</p><p><strong>拆解</strong></p><ul><li>runs 表示动作，有实在意义、能单独作谓语，是实义动词</li><li>is 不表示具体动作，只把主语 She 和后面的 a doctor 连起来，是系动词</li><li>一个句子只有一个谓语动词，先认出这个动词的身份，才能判断句子是主谓宾还是主系表</li></ul><p><strong>语法</strong>：动词是表示动作或状态的词。分类总口诀“情 义 助 你 系 鞋 带”对应情态动词、实义动词、助动词、系动词四类。实义动词有实在意义，能单独作谓语；系动词连接主语和表语；助动词帮助主要动词构成时态、语态、否定与疑问；情态动词本身有词义但不能单独作谓语，只能和动词原形一起构成谓语。</p><p>正例：She runs every morning.（实义动词作谓语）；She is a doctor.（系动词连接主语与表语）；He is playing football.（be 作助动词，与 doing 构成进行时）；He can fly.（情态动词 + 动词原形作谓语） 反例：把 She is playing 里的 is 当系动词 ×（这里 is 是助动词，与 playing 一起作谓语）；把 can 当作能单独作谓语的实义动词 ×（情态动词必须和动词原形一起构成谓语） 适用边界：同一个词在不同句子里可能属于不同类别：is 在 She is a doctor. 里是系动词，在 She is reading. 里是助动词；need 和 dare 既可作情态动词也可作实义动词。先把句子里的动词拿出来，再看它的搭配，才能定身份。</p><p><strong>口诀</strong>：情 义 助 你 系 鞋 带 —— 用谐音串起四类动词：情态、实义、助动词、系动词。“系鞋带”提醒你“系”这一类后面必须接表语，否则句子不完整，借此一眼认出系动词。</p></div><p>动词（v.）：表示<strong>动作或状态</strong>的词。</p><p>She <strong>runs</strong> every morning. / She <strong>takes</strong> care of her sister.（动作）</p><p>She <strong>is</strong> a doctor. / The dog <strong>is</strong> cute.（状态）</p><h2 id="第二部分-·-实义动词-教材-p42–45" tabindex="-1"><a class="header-anchor" href="#第二部分-·-实义动词-教材-p42–45"><span>第二部分 · 实义动词（教材 P42–45）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二部分 · 实义动词（教材 P42–45）</p><ul><li><strong>目标</strong>：解决“这个动词后面能接什么”：分清不及物与及物，选对双宾语的 to / for，并认全宾补的六种形式。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>不及物动词 vi. 与及物动词 vt.</code> <code>双宾语与 to / for 的选择</code> <code>复合宾语：vt. + sb. + 宾补的六种形式</code></li></ul></div><h3 id="第二部分-·-实义动词-教材-p42–45-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二部分-·-实义动词-教材-p42–45-·-小步学"><span>第二部分 · 实义动词（教材 P42–45） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 1 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>动词：说出动作或状态</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>rise 还是 raise：看后面有没有宾语</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>Hand me that book 还是 Hand that book for me：to 与 for 的分工</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>make her tell 还是 make her to tell：宾补的六种形式</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：用 rise/raise、wait for 各造一句，说明为什么宾语的有无决定 vi./vt.；再举出一个 to 类双宾语动词和一个 for 类双宾语动词，并各改写一次介词结构。</p><div class="hint-container tip"><p class="hint-container-title">rise 还是 raise：看后面有没有宾语</p><p><strong>句意</strong>：The sun rises in the east every day, and we should raise our hands when we have questions. 意思是“太阳每天从东方升起，我们有问题时应该举手”。</p><p><strong>拆解</strong></p><ul><li>The sun rises：rise 后面没有宾语，太阳自己升起，是不及物动词</li><li>raise our hands：raise 后面跟宾语 our hands，把某物举起来，是及物动词</li><li>两个词意思相近，但一个说自己动、一个说对别的东西施力，这就决定了它们是 vi. 还是 vt.</li></ul><p><strong>语法</strong>：不及物动词 vi. 不能直接跟宾语（smile、wait、die、rise），要接宾语得先加介词：look at、listen to、wait for、arrive in/at。及物动词 vt. 能直接跟宾语（love、raise、accept、celebrate）。少数动词兼作 vi. 和 vt.：He left yesterday.（不及物）／He left Beijing yesterday.（及物）。</p><p>正例：The boy smiled when he saw his mother.（vi.）；I am still waiting for my bus.（vi. + 介词后再接宾语）；The sun rises in the east.（vi.，rise 后没有宾语）；She raised her hand.（vt.，后跟宾语 her hand） 反例：The sun raises in the east. ×（raise 是及物动词，后面必须有宾语）；We should rise our hands. ×（rise 是不及物动词，不能带宾语，应改为 raise）；I am waiting my bus. ×（wait 是不及物动词，要加 for 才能接宾语） 适用边界：判断 vi. 还是 vt.，只看它后面能不能直接出现宾语：能，就是及物；不能，就是不及物，接了介词之后才算带宾语。rise/raise、lie/lay 这类成对词词形相近而词性相反，做题时先看宾语在不在。</p><p><strong>口诀</strong>：带 a 的 raise 要带宾语，没有 a 的 rise 自己走 —— raise 多出来的 a 就像“一只托着东西的手”，句子里必须有被托起的东西作宾语；rise 没有这只手，主语自己上升。</p></div><div class="hint-container tip"><p class="hint-container-title">Hand me that book 还是 Hand that book for me：to 与 for 的分工</p><p><strong>句意</strong>：Hand me that book, please. = Hand that book to me, please. 意思是“请把那本书递给我”；My parents bought me a nice backpack. = My parents bought a nice backpack for me. 意思是“父母给我买了个好看的背包”。</p><p><strong>拆解</strong></p><ul><li>Hand me that book：me 是间接宾语（人），that book 是直接宾语（物）</li><li>把直接宾语提前后，间接宾语前要加介词：Hand that book to me.（hand 属 to 类）</li><li>bought me a nice backpack：改成介词结构时用 for → bought a nice backpack for me</li></ul><p><strong>语法</strong>：加双宾语的及物动词结构是 vt. + sb. + sth.，也可改写成 vt. + sth. + to/for sb.。用 to 的动词（give、hand、lend、offer、owe、pass、post、promise、read、return、send、show、teach、tell、write）表示动作要在对方那里完成；用 for 的动词（buy、cook、draw、find、make、order、prepare、spare、save）表示对方不参与这个动作。</p><p>正例：Hand me that book, please. = Hand that book to me.；My parents bought me a nice backpack. = … bought a nice backpack for me.；send / show / teach / write 类动词用 to；buy / make / cook / draw 类动词用 for 反例：Hand that book for me. ×（hand 属 to 类）；My parents bought a nice backpack to me. ×（buy 属 for 类）；I will explain you the rule. ×（explain 不能带双宾语，要说 explain the rule to you） 适用边界：两类的分界线是“对方有没有参与这个动作”：动作必须在对方那里才完成（东西只有送到才叫“送”）用 to；对方全程不参与（买、做、画都是自己动手）用 for。少数动词根本不能带双宾语，如 explain、suggest、announce，要改成 explain sth. to sb.。</p><p><strong>口诀</strong>：给递借寄教告诉用 to，买做画找留准备用 for —— to 类动词的共同点是东西要从说话人这边转到对方手里，动作到对方那里才算完；for 类是自己做完再交给对方，对方全程没动手。</p></div><div class="hint-container tip"><p class="hint-container-title">make her tell 还是 make her to tell：宾补的六种形式</p><p><strong>句意</strong>：John made her tell him everything. 意思是“约翰让她把一切都告诉了他”；I must get my watch fixed. 意思是“我得把表修一修”。</p><p><strong>拆解</strong></p><ul><li>make her tell：her 是宾语，tell 补充说明她做了什么，构成“vt. + 宾语 + 宾补”</li><li>get my watch fixed：my watch 是宾语，fixed 补充说明表被修，用过去分词表被动</li><li>宾补的形式由前面的动词决定：make 后接不带 to 的不定式，get 后接过去分词</li></ul><p><strong>语法</strong>：加复合宾语的及物动词结构是 vt. + sb. + 宾补，宾补有六种形式：形容词（Keep the window open.）、名词短语（We consider him a strange person.）、不定式 to do（Don&#39;t allow problems to worry you.）、不带 to 的不定式（John made her tell him everything.）、现在分词（Don&#39;t keep your children watching TV.）、过去分词（I must get my watch fixed.）。宾补与宾语之间有逻辑上的主表关系：宾语 + be + 宾补说得通。</p><p>正例：Keep the window open.（形容词作宾补）；We consider him a strange person.（名词短语作宾补）；I must get my watch fixed.（过去分词作宾补，表被动）；Don&#39;t keep your children watching TV all the time.（现在分词作宾补，表主动进行） 反例：John made her to tell him everything. ×（make 后作宾补的不定式不带 to）；Don&#39;t allow problems worry you. ×（allow 后的宾补必须带 to：allow sb. to do）；I must get my watch fixing. ×（表“表被修”要用过去分词 fixed） 适用边界：宾补六种形式里只有不定式要看动词脸色：make、let、have 等使役动词和感官动词后用不带 to 的不定式，allow、ask、want 等要用带 to 的不定式。现在分词与过去分词的分工是“主动进行”与“被动完成”。</p><p><strong>口诀</strong>：宾补六形式：形容词、名词短语、to do、不带 to 的 do、doing、done —— 先看句型里有没有宾语（没有宾语就谈不上宾补），再看宾补与宾语之间是主表关系还是动作关系——是“变成什么样”就用形容词或名词，是“做了什么、被怎么处理”就用不定式或分词。</p></div><h3 id="_1-不及物动词-vi-不能-直接-跟宾语" tabindex="-1"><a class="header-anchor" href="#_1-不及物动词-vi-不能-直接-跟宾语"><span>1. 不及物动词 vi.：不能（直接）跟宾语</span></a></h3><p>The boy <strong>smiled</strong> when he saw his mother.（男孩看到妈妈时笑了）</p><p>We <strong>waited</strong> until Mom came.（一直等到妈妈回来）</p><p>My pet dog <strong>died</strong> yesterday.（宠物狗昨天去世了）</p><p>You jump. I jump.（你跳，我跳）</p><p>I am still <strong>waiting</strong> for my bus.（仍在等公交车）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>常见“不及物动词 + 介词”再接宾语看 look <strong>at</strong>、听 listen <strong>to</strong>、等 wait <strong>for</strong>、到 arrive <strong>in/at</strong>：look <strong>at</strong> me；listen <strong>to</strong> music</p></div><h3 id="_2-及物动词-vt-能跟宾语" tabindex="-1"><a class="header-anchor" href="#_2-及物动词-vt-能跟宾语"><span>2. 及物动词 vt.：能跟宾语</span></a></h3><p><strong>① 加一个宾语的及物动词</strong>（教材 P42–43 词表）：accept 接受、admire 羡慕、admit 承认、affect 影响、afford 买得起/付得起、announce 宣布、borrow 借入、bury 埋、celebrate 庆祝、cover 覆盖、defeat 击败、defend 捍卫、destroy 毁坏、devote 致力、discover 发现、educate 教育、enjoy 喜欢、explain 解释、forget 忘记、guess 猜想、invent 发明、interest 使感兴趣、love 热爱、raise 举起</p><p><strong>② 加双宾语的及物动词</strong>：结构 <strong>vt. + sb. + sth. = vt. + sth. + to/for sb.</strong></p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>用 to 还是 for（教材 P43） <strong>to</strong>：动作在<strong>对方这里截止</strong>才算完成（如 send，只有送到对方手里，“送”才完成）；</p><p><strong>for</strong>：对方<strong>不参与</strong>这个动作，如 I buy an apple <strong>for</strong> him.（“他”不参与“买”）。</p></div><table><thead><tr><th>直接宾语提前后加</th><th>动词</th><th>例句</th></tr></thead><tbody><tr><td><strong>to</strong></td><td>give 给、hand 递、lend 借给、offer 提供、owe 归功于、pass 递、post 寄、promise 答应、read 读、return 归还、send 送、show 展示、teach 教、tell 告诉、write 写</td><td><strong>Hand me</strong> that book, please. = Hand that book <strong>to me</strong>, please.（请把那本书递给我）</td></tr><tr><td><strong>for</strong></td><td>buy 买、cook 烹饪、draw 画、find 找到、make 做、order 订购、prepare 准备、spare 抽出、save 保留</td><td>My parents <strong>bought me</strong> a nice backpack. = My parents bought a nice backpack <strong>for me</strong>.（父母给我买了个好看的背包）</td></tr></tbody></table><p><strong>③ 加复合宾语的及物动词</strong>：结构 <strong>vt. + sb. + 宾补</strong>（教材 P44–45，宾补可以是 6 种形式）：</p><table><thead><tr><th>宾补形式</th><th>例句</th></tr></thead><tbody><tr><td>形容词</td><td>Keep the window <strong>open</strong>.</td></tr><tr><td>名词短语</td><td>We consider him <strong>a strange person</strong>.</td></tr><tr><td>不定式 to do</td><td>Don&#39;t allow problems <strong>to worry</strong> you all the time.</td></tr><tr><td>不带 to 的不定式</td><td>John made her <strong>tell</strong> him everything.</td></tr><tr><td>现在分词</td><td>Don&#39;t keep your children <strong>watching</strong> TV all the time.</td></tr><tr><td>过去分词</td><td>I must get my watch <strong>fixed</strong>, for it often stops.</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>注意少数动词<strong>既是 vi. 也是 vt.</strong>：He <strong>left</strong> yesterday.（不及物：他昨天就走了）He <strong>left</strong> Beijing yesterday.（及物：他昨天离开了北京）</p></div><h2 id="第三部分-·-系动词-教材-p45" tabindex="-1"><a class="header-anchor" href="#第三部分-·-系动词-教材-p45"><span>第三部分 · 系动词（教材 P45）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第三部分 · 系动词（教材 P45）</p><ul><li><strong>目标</strong>：解决“这是主系表还是主谓宾”：背熟五感五变三保持两结果一是一像，并守住“be 后不能加动词原形”这条铁律。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>系动词：五感五变三保持两结果一是一像</code></li></ul></div><h3 id="第三部分-·-系动词-教材-p45-·-小步学" tabindex="-1"><a class="header-anchor" href="#第三部分-·-系动词-教材-p45-·-小步学"><span>第三部分 · 系动词（教材 P45） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 2 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>动词：说出动作或状态</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>The music sounded wonderful：系动词后面跟的是形容词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>be 后面能加什么：六选一，就是不能跟动词原形</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：一口气背出五感、五变、三保持、两结果、一是、一像；再用 keep/stay/remain 各造一个“保持”的句子。</p><div class="hint-container tip"><p class="hint-container-title">The music sounded wonderful：系动词后面跟的是形容词</p><p><strong>句意</strong>：The music sounded wonderful. 意思是“这音乐听起来很棒”；The song sounds beautiful. 意思是“这首歌听起来真好听”。</p><p><strong>拆解</strong></p><ul><li>主语是 The music，谓语是 sounded，后面的 wonderful 是表语</li><li>sounded 不表示“发出声音”这个动作，只把主语与它的特征连起来，是感官系动词</li><li>所以句子是主系表，而不是主谓宾——判断的关键是谓语有没有“动作”的意思</li></ul><p><strong>语法</strong>：系动词连接主语和表语构成系表结构。口诀：五感 look/sound/feel/taste/smell；五变 become/get/turn/go/grow/come；三保持 keep/stay/remain；两结果 prove/turn out；一是 be（am/is/are/was/were）；一像 seem。区分主谓宾与主系表：主谓宾的核心是动作（I love you.），主系表的核心是状态（I am a teacher.）。</p><p>正例：You look beautiful today.（看起来）；The song sounds beautiful.（听起来）；The cake tastes good.（尝起来）；Her face turned red.（变）；She remained poor after the hard work.（保持）；Your answers prove wrong.（结果） 反例：把 The music sounded wonderful. 里的 sounded 当实义动词 ×（它是感官系动词，后面跟表语 wonderful）；The flower smells well. ×（表示“闻起来香”要用形容词 good，不是副词 well） 适用边界：感官动词也能作实义动词：The dog smells the bone.（闻骨头，及物）与 The soup smells good.（闻起来香，系动词）——区别在于后面跟的是名词宾语还是形容词表语。系动词后面要用形容词作表语，不能用副词。</p><p><strong>口诀</strong>：五感五变三保持，两结果一是又一像 —— 五感=look/sound/feel/taste/smell；五变=become/get/turn/go/grow/come；三保持=keep/stay/remain；两结果=prove/turn out；一是=be；一像=seem。遇到“保持安静用哪个词”这类题，直接把三保持整组拿出来逐一核对。</p></div><div class="hint-container tip"><p class="hint-container-title">be 后面能加什么：六选一，就是不能跟动词原形</p><p><strong>句意</strong>：She is reading. 意思是“她正在读书”；She is to meet her friends. 意思是“她就要去见她的朋友了”。</p><p><strong>拆解</strong></p><ul><li>She is reading：be + doing 构成进行时，表示正在发生</li><li>She is fired：be + done 构成被动语态</li><li>She is to meet her friends：be + to do 表示按计划要发生的将来</li><li>be + 名词 / 形容词 / 介词短语 分别表示“是什么、什么样的、在哪里”</li></ul><p><strong>语法</strong>：be 动词后可以加名词（It is an apple.）、形容词（She is sleepy.）、介词短语（I am in Jinan.）、doing（She is reading.）、done（She is fired.）、to do（She is to meet her friends.），分别表示身份、性质、位置、进行、被动、将来。be 动词后永远不能直接加动词原形。</p><p>正例：It is an apple.（be + n.）；She is sleepy.（be + adj.）；I am in Jinan.（be + 介词短语）；She is reading.（be + doing）；She is fired.（be + done）；She is to meet her friends.（be + to do） 反例：She is sleep. ×（be 后不能直接跟动词原形，应写 sleepy 或 is sleeping）；I am go to school. ×（一般现在时直接用 go，不必加 be）；It is a apple. ×（apple 以元音音素开头，要用 an） 适用边界：be 后不能接动词原形，但可以接不定式 to do（表将来计划），两者不能混为一谈：is to meet 里的 to 不能省。表示“保持……”这种状态时用 keep/stay/remain + 形容词，也不再另外加 be。</p><p><strong>口诀</strong>：be 后六选一：名词、形容词、介词短语、doing、done、to do；就是不能跟原形 —— 把 be 看成一个“等号”，等号右边必须是能说明主语状态或身份的成分；裸动词原形不说明状态，所以站不到等号右边。</p></div><p>连接<strong>主语和表语</strong>的动词，后跟表语构成<strong>系表结构</strong>，说明主语的状况、性质、特征等。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>区分主谓宾 &amp; 主系表<strong>主谓宾</strong>：核心是<strong>动作</strong>（I love you.）；<strong>主系表</strong>：核心是<strong>状态</strong>（I am a teacher.）</p></div><table><thead><tr><th>类别</th><th>动词</th></tr></thead><tbody><tr><td>结果类</td><td>prove, turn out</td></tr><tr><td>状态类</td><td>be, keep, stay, remain, lie, stand</td></tr><tr><td>变化类</td><td>become, get, grow, turn, go, come</td></tr><tr><td>感官类</td><td>look, smell, sound, feel, taste</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀 <strong>五感</strong>：look, sound, feel, taste, smell</p><p><strong>五变</strong>：become, get, turn, go, grow, come</p><p><strong>三保持</strong>：keep, stay, remain</p><p><strong>两结果</strong>：prove, turn out</p><p><strong>一是</strong>：be（am/is/are/was/were）</p><p><strong>一像</strong>：seem</p></div><p>各例句：</p><ul><li>be：I <strong>am</strong> happy. 我很开心 / He <strong>is</strong> a boy. / You <strong>are</strong> right.</li><li>保持：It <strong>keeps</strong> raining.（雨一直下）He <strong>stayed</strong> happy after the disease.（病后仍保持开朗）She <strong>remained</strong> poor after the hard work.（努力工作后仍很贫穷）</li><li>变化：Her face <strong>turned/got/became/grew</strong> red.（她的脸变红了）</li><li>感官：You <strong>look</strong> beautiful today.（看起来真漂亮）The song <strong>sounds</strong> beautiful.（听起来真好听）The new shirt <strong>feels</strong> good.（感觉不错）The flower <strong>smells</strong> good.（闻起来真香）The cake <strong>tastes</strong> good.（尝起来不错）</li><li>结果：Your answers <strong>prove/turn out to be</strong> wrong.（你的答案结果是错误的）</li></ul><p><strong>be 动词后加什么？</strong></p><table><thead><tr><th>结构</th><th>含义</th><th>例</th></tr></thead><tbody><tr><td>be + n.</td><td>是什么</td><td>It is <strong>an apple</strong>.</td></tr><tr><td>be + adj.</td><td>什么样的</td><td>She is <strong>sleepy</strong>.</td></tr><tr><td>be + 介词短语</td><td>在哪里</td><td>I am <strong>in Jinan</strong>.</td></tr><tr><td>be + doing</td><td>正在进行</td><td>She is <strong>reading</strong>.</td></tr><tr><td>be + done</td><td>被动</td><td>She is <strong>fired</strong>.</td></tr><tr><td>be + to do</td><td>表将来</td><td>She is <strong>to meet</strong> her friends.</td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">易错</p><p>切记<strong>be 动词后永远不能加动词原形</strong>！</p></div><h2 id="第四部分-·-助动词-教材-p46" tabindex="-1"><a class="header-anchor" href="#第四部分-·-助动词-教材-p46"><span>第四部分 · 助动词（教材 P46）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第四部分 · 助动词（教材 P46）</p><ul><li><strong>目标</strong>：解决“否定句怎么变”：记住四大帮手 do/have/be/will，并会用“有情有 be 直接加 not，无情无 be 才请 do”两条变法。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>助动词四大帮手 do / have / be / will</code></li></ul></div><h3 id="第四部分-·-助动词-教材-p46-·-小步学" tabindex="-1"><a class="header-anchor" href="#第四部分-·-助动词-教材-p46-·-小步学"><span>第四部分 · 助动词（教材 P46） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 2 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>动词：说出动作或状态</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>四大帮手：do、have、be、will</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>I should not run fast 与 I am not a student：否定句的两条变法</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出助动词的四大帮手各自负责什么；再把“He likes apples.”改写成否定句和一般疑问句，说明每一步为什么用 does。</p><div class="hint-container tip"><p class="hint-container-title">四大帮手：do、have、be、will</p><p><strong>句意</strong>：He is playing football right now. 意思是“他现在正在踢足球”；I have finished my homework. 意思是“我已经做完作业了”。</p><p><strong>拆解</strong></p><ul><li>is playing：be 作助动词，与 doing 一起构成进行时</li><li>have finished：have 作助动词，与过去分词一起构成完成时</li><li>The story is told again：be + done 构成被动语态</li><li>We will talk about it tomorrow：will + 动词原形构成将来时</li></ul><p><strong>语法</strong>：谓语动词有四大帮手：be、do、have、will。be + doing 构成进行时，be + done 构成被动语态；do/does/did 构成否定句与疑问句，并帮助构成强调句与倒装句；have/has/had + 过去分词构成完成时；will + 动词原形构成将来时。</p><p>正例：He is playing football right now.（进行）；The story is told again.（被动）；I have finished my homework.（完成）；We will talk about it tomorrow.（将来）；I do love you.（强调谓语用 do）；Only yesterday did he find out that his watch was missing.（倒装） 反例：He is play football. ×（be 后不能跟动词原形，要用 playing）；I have finish my homework. ×（have 后要用过去分词 finished） 适用边界：助动词不能单独作谓语：is 只有在和 doing/done 搭配时才叫助动词，单独带名词或形容词时它是系动词（She is sleepy.）。强调谓语只能用 do/does/did，不能借 be 或 have。</p><p><strong>口诀</strong>：谓语有四大帮手：do、have、be、will —— 帮手自己不干活，只帮实义动词带上时态、语态、否定和疑问；看到这四类词先问一句“它是在帮忙，还是自己在作谓语”。</p></div><div class="hint-container tip"><p class="hint-container-title">I should not run fast 与 I am not a student：否定句的两条变法</p><p><strong>句意</strong>：I should run fast. → I should not run fast. 意思是“我应该跑得快。→ 我不应该跑得快”；I am a student. → I am not a student. 意思是“我是一名学生。→ 我不是一名学生”。</p><p><strong>拆解</strong></p><ul><li>第一句里有情态动词 should，否定时直接在 should 后面加 not，其他成分不动</li><li>第二句里有 be 动词 am，同样直接在 am 后面加 not</li><li>两句都不需要借助 don&#39;t/doesn&#39;t/didn&#39;t，因为情态动词和 be 自己就能承载否定</li></ul><p><strong>语法</strong>：变否定句有两条路。变法 1：句中有情态动词（should/may/can/must/will/might/could）或 be 动词时，直接在其后加 not。变法 2：既没有情态动词也没有 be 动词时，在主语后加 don&#39;t/doesn&#39;t/didn&#39;t——一般过去时用 didn&#39;t，一般现在时主语是第三人称单数用 doesn&#39;t，其余用 don&#39;t。</p><p>正例：I should not run fast.（情态动词后加 not）；I am not a student.（be 后加 not）；He doesn&#39;t like cats.（三单用 doesn&#39;t，后面动词回原形）；They don&#39;t speak English.（其余用 don&#39;t）；The picture didn&#39;t show us profound meaning.（过去时用 didn&#39;t） 反例：把 I should run fast. 改成 I don&#39;t run fast. ×（句中有情态动词就该走变法 1）；I not am a student. ×（not 要放在 be 之后）；He doesn&#39;t likes cats. ×（doesn&#39;t 后面的动词要用原形） 适用边界：两条变法的开关是“句子里有没有情态动词或 be 动词”：有 → 直接加 not；没有 → 才借 don&#39;t/doesn&#39;t/didn&#39;t。用 do 类助动词构成否定时，实义动词必须还原成原形（He doesn&#39;t like.，不是 doesn&#39;t likes）。</p><p><strong>口诀</strong>：有情有 be 直接加 not，无情无 be 才请 do —— “情”指情态动词、“be”指 be 动词，这两种词自己就能承载否定，所以 not 直接贴上；两者都没有时只能请 do/does/did 出面，请了帮手，实义动词就退回原形。</p></div><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>记忆锚点<strong>谓语动词有四大帮手：do、have、be 和 will</strong>，这四个帮手统称助动词，它们来协助谓语动词。</p></div><table><thead><tr><th>类别</th><th>形式</th><th>功能</th></tr></thead><tbody><tr><td>be 类</td><td>be + doing / be + done</td><td>构成<strong>进行时</strong> / 构成<strong>被动语态</strong></td></tr><tr><td>do 类</td><td>do、does、did</td><td>构成<strong>否定句或疑问句</strong>；辅助构成<strong>强调句、倒装句</strong></td></tr><tr><td>have 类</td><td>have/has/had + 过去分词</td><td>构成<strong>完成时态</strong></td></tr><tr><td>will 类</td><td>will + 动词原形</td><td>构成<strong>将来时态</strong></td></tr></tbody></table><p>He <strong>is playing</strong> football right now.（进行）/ The story <strong>is told</strong> again.（被动）/ I <strong>have finished</strong> my homework.（完成）/ We <strong>will talk</strong> about it tomorrow.（将来）/ He <strong>is playing</strong>.（他正在玩）/ You <strong>are loved</strong>.（你被爱着）</p><p><strong>do 类助动词详解</strong></p><ol><li><strong>构成否定句</strong>——变法 1：陈述句中有<strong>情态动词</strong>（should/may/can/must/will/might/could）或 <strong>be 动词</strong>时，直接在其后面加 not：I should run fast. → I should <strong>not</strong> run fast.；I am a student. → I am <strong>not</strong> a student.</li><li><strong>构成否定句</strong>——变法 2：既没有情态动词也没有 be 动词时，在主语后面加 <strong>don&#39;t/doesn&#39;t/didn&#39;t</strong>（一般过去时加 didn&#39;t；一般现在时主语三单加 doesn&#39;t；其他情况加 don&#39;t）：The picture <strong>didn&#39;t</strong> show us profound meaning. / He <strong>doesn&#39;t</strong> like cats. / They <strong>don&#39;t</strong> speak English.</li><li><strong>构成疑问句</strong>：疑问句语序 = <strong>助动词 + 主语 + 动词原形 + 其他</strong>：Mike likes apples. → <strong>Does</strong> Mike <strong>like</strong> apples? — Yes, he does. / No, he doesn&#39;t.</li><li><strong>帮助构成强调</strong>（强调谓语只能用 do/does/did）：I <strong>do</strong> love you. Please trust me.（我真的爱你，请相信我）</li><li><strong>帮助构成倒装</strong>：Only yesterday <strong>did</strong> he find out that his watch was missing.（就在昨天，他发现手表不见了）</li></ol><p><strong>have 类</strong>：现在完成时 have/has + done；过去完成时 had + done：He <strong>has been</strong> in this school for many years. / When the bus came, I <strong>had waited</strong> at the station for 20 minutes.</p><p><strong>will 类</strong>：will + do；will 的过去式是 <strong>would</strong>；缩写 <strong>won&#39;t = will not</strong></p><h2 id="第五部分-·-情态动词-教材-p46–54-·-考试重点" tabindex="-1"><a class="header-anchor" href="#第五部分-·-情态动词-教材-p46–54-·-考试重点"><span>第五部分 · 情态动词（教材 P46–54 · 考试重点）</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第五部分 · 情态动词（教材 P46–54 · 考试重点）</p><ul><li><strong>目标</strong>：解决“这个空填哪个情态动词”：用好“不随主语变 / 后接动词原 / 变否加 not / 变疑要提前”，认准 must 与 needn&#39;t 的区别，并按时间对号入座表猜测三张表。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>情态动词的基本用法与虚拟</code> <code>情态动词表猜测的三张表</code></li></ul></div><h3 id="第五部分-·-情态动词-教材-p46–54-·-考试重点-·-小步学" tabindex="-1"><a class="header-anchor" href="#第五部分-·-情态动词-教材-p46–54-·-考试重点-·-小步学"><span>第五部分 · 情态动词（教材 P46–54 · 考试重点） · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>动词：说出动作或状态</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>情态动词的四条形态纪律</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>needn&#39;t 与 mustn&#39;t：不必和禁止是两回事</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>表猜测三张表：原形管现在、be doing 管正在、have done 管过去</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：背出情态动词用法口诀，并说出 must 问句与 may 问句各自的否定回答；再用 must be doing、must have done 各造一句表推测的句子。</p><div class="hint-container tip"><p class="hint-container-title">情态动词的四条形态纪律</p><p><strong>句意</strong>：He can fly. / He can not fly. / Can he fly? 意思是“他会飞。／他不会飞。／他会飞吗？”</p><p><strong>拆解</strong></p><ul><li>can 没有第三人称单数形式，主语换成 he 也不加 s，这就是“不随主语变”</li><li>can 后面跟动词原形 fly，不能写成 flew 或 to fly</li><li>否定句直接在 can 后加 not；疑问句把 can 提到主语前面</li></ul><p><strong>语法</strong>：情态动词本身有词义，但不能单独作谓语，只能和动词原形一起构成谓语，表示说话人的情绪、态度、语气。用法口诀：不随主语变 / 后接动词原 / 变否加 not / 变疑要提前。常考词：can/could、may/might、must、have to、shall、should、ought to、will/would、dare、need、used to。</p><p>正例：He can fly.（无人称和数的变化）；He can not fly.（否定句直接在其后加 not）；Can he fly?（疑问句提前到句首）；You should/ought to get up early.（应该）；I used to go to bed late.（过去常常） 反例：He cans fly. ×（情态动词不随主语变）；He can flies. ×（情态动词后接动词原形）；He not can fly. ×（not 要跟在情态动词之后） 适用边界：must 表“必须”时没有时态和第三人称单数变化，“不得不”要用有时态变化的 have to。dare 与 need 既能作情态动词（多用于否定句和疑问句）也能作实义动词，作实义动词时 dare 常接 to do，need 接 to do 或 doing。</p><p><strong>口诀</strong>：不随主语变，后接动词原，变否加 not，变疑要提前 —— 四句话对应四件事：不加 -s、后面跟原形、否定贴 not、疑问提到句首。做题时按这四条逐条检查，就能一次排掉所有形态错误。</p></div><div class="hint-container tip"><p class="hint-container-title">needn&#39;t 与 mustn&#39;t：不必和禁止是两回事</p><p><strong>句意</strong>：You needn&#39;t finish the work today; tomorrow is also OK. 意思是“你今天不必完成这项工作，明天也可以”；You mustn&#39;t smoke here. 意思是“你禁止在这里吸烟”。</p><p><strong>拆解</strong></p><ul><li>needn&#39;t 表示“不必”，所以后半句才能接“明天也可以”</li><li>mustn&#39;t 表示“禁止、不许”，是命令语气，与“明天也可以”自相矛盾</li><li>两个词都是否定形式，区别在“没有必要”还是“不允许”</li></ul><p><strong>语法</strong>：must 表说话人主观看法“一定要”，无时态与三单变化；have to 强调客观条件“不得不”，有时态与三单变化。must 问句的否定回答用 needn&#39;t / don&#39;t have to（不必）；may 问句的否定回答用 mustn&#39;t（禁止）/ can&#39;t（不允许）。shall 除表将来外，用在法律、规则、条款里表示义务、规定。need 作情态动词多用于否定句和疑问句；作实义动词时，主语是人用 need to do，主语是物用 need doing = need to be done。</p><p>正例：Must I go now? — No, you needn&#39;t / don&#39;t have to.（不必）；May I use your pen? — No, you mustn&#39;t / can&#39;t.（禁止／不允许）；Under the regulations, all the passengers shall remain in their seats.（规章中的义务规定）；The car needs repairing. = The car needs to be repaired.（物作主语） 反例：回答 Must I go now? 用 No, you mustn&#39;t. ×（这里是“不必”，应用 needn&#39;t）；回答 May I use your pen? 用 No, you may not. ×（规范答法用 mustn&#39;t / can&#39;t）；The car needs to repair. ×（主语是物要用 need doing 或 need to be done） 适用边界：mustn&#39;t 是“禁止”，needn&#39;t 是“不必”，不能互换；回答 must 问句用 needn&#39;t，回答 may 问句才用 mustn&#39;t。shall 表“义务规定”只出现在法律、规章、合同这类文本里，日常句子里的 shall 仍是将来时。</p><p><strong>口诀</strong>：must 问句答 needn&#39;t（不必），may 问句答 mustn&#39;t（禁止） —— 谁问谁负责：must 问的是“我必须吗”，答案只能是不必；may 问的是“我可以吗”，答案是不许或不可以。</p></div><div class="hint-container tip"><p class="hint-container-title">表猜测三张表：原形管现在、be doing 管正在、have done 管过去</p><p><strong>句意</strong>：He must be working in his office now. 意思是“他现在肯定正在办公室工作”；You must have seen the answers. 意思是“你一定已经看到答案了”。</p><p><strong>拆解</strong></p><ul><li>must be working：对此刻正在发生的事作极为肯定的推测，用 must + be doing</li><li>You must have seen：对过去已经发生的事作非常肯定的推测，用 must + have done</li><li>对现在状态的推测则用 must + 动词原形：She must be in the classroom now.</li></ul><p><strong>语法</strong>：情态动词表猜测有三张表。① 对现在状态（+ 动词原形）：must 非常肯定、may/might 较不确定、can&#39;t 强烈否定，can 只用于疑问句。② 对正在发生的事（+ be doing）：must be doing 极为肯定、may/might be doing 可能、can&#39;t be doing 不可能。③ 对过去的事（+ have done）：must have done 一定已经、may/might have done 可能已经、can&#39;t have done 不可能已经。可能性排序：must &gt; should &gt; may &gt; might &gt; could &gt; can&#39;t（否定推测）。can 表推测只用于否定句和疑问句，肯定句的“可能”用 may/might/could。</p><p>正例：She must be in the classroom now.（对现在的肯定推测）；He must be working in his office now.（对正在发生的肯定推测）；You must have seen the answers.（对过去的肯定推测）；She can&#39;t be at home.（强烈否定现在的推测）；Could she be a teacher?（疑问推测） 反例：把肯定句的“可能”用 can：She can be in the classroom now. ×（can 表推测不用于肯定句）；把对过去的推测写成 must be work yesterday ×（要用 must have worked）；把疑问句的推测用 must：Must she be at home? ×（must 表推测不用于疑问句，用 Can/Could she be at home?） 适用边界：三张表按时间分工：动词原形管现在、be doing 管正在、have done 管过去，选词前先确定说的是哪个时间。can/can&#39;t 只负责否定与疑问，肯定句的“可能”交给 may/might/could。must 表“必须”时不能随时态变化，但表推测时后面可以接 be doing、have done 这些结构。</p><p><strong>口诀</strong>：肯定用 must，否定用 can&#39;t，可能用 may/might；原形管现在、be doing 管正在、have done 管过去 —— 两步走：先定时间（现在／正在／过去）选结构，再定把握大小选情态动词——把握最大 must，最不确定 might，否定最强 can&#39;t。</p></div><p>情态动词<strong>本身有词义</strong>，<strong>不能单独用作谓语</strong>，只能和<strong>动词原形</strong>一起构成谓语，表示说话人的<strong>情绪、态度、语气</strong>。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>不随主语变 / 后接动词原 / 变否加 not / 变疑要提前</strong></p><p>肯：He <strong>can</strong> fly.（无人称和数的变化）　否：He <strong>can not</strong> fly.（否定句直接在其后加 not）　疑：<strong>Can</strong> he fly?（疑问句将其提前到最前）</p></div><p>前置课分类：can、could：可以——<strong>Can/Could</strong> you help me?；may、might：可能——I <strong>may/might</strong> catch a cold.；will、would：会——I <strong>will/would</strong> love you forever.；must、have to：必须——You <strong>must/have to</strong> do your homework.；should、ought to：应该——You <strong>should/ought to</strong> get up early.；used to：过去常常，曾经……——I <strong>used to</strong> go to bed late.</p><h3 id="_1-can-could" tabindex="-1"><a class="header-anchor" href="#_1-can-could"><span>1. can / could</span></a></h3><ol><li><strong>能力</strong>“会、能”（could 是 can 的过去式）：I <strong>can</strong> speak three languages.</li><li><strong>请求和允许</strong>（could 语气更委婉）：<strong>Can</strong> I have a glass of water?</li><li><strong>推测</strong>（can 用于否定和疑问语气；can&#39;t 表示“不可能”）：It <strong>can&#39;t</strong> be true.（这不可能是真的）</li></ol><h3 id="_2-may-might" tabindex="-1"><a class="header-anchor" href="#_2-may-might"><span>2. may / might</span></a></h3><ol><li><strong>请求和允许</strong>（might 更委婉）：<strong>May</strong> I use your pen? / You <strong>may</strong> go now.</li><li><strong>推测</strong>（might 可能性比 may 小）：It <strong>may</strong> rain this afternoon.</li><li><strong>祝愿</strong>（多用祈使句）：<strong>May</strong> you succeed!</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>问句回答<strong>may</strong> 问句：肯定 Yes, 主语 + may.；否定 No, 主语 + <strong>mustn&#39;t</strong>.（禁止）或 No, 主语 + <strong>can&#39;t</strong>.（不允许）。<strong>might</strong> 问句：肯定 Yes, 主语 + might.；否定 No, 主语 + might not.</p></div><h3 id="_3-must" tabindex="-1"><a class="header-anchor" href="#_3-must"><span>3. must</span></a></h3><ol><li><strong>偏要、必须</strong>（主观或责任驱使）：You <strong>must</strong> wear a seat-belt in the car.</li><li><strong>肯定推测</strong>（表推测时 must 可能性最大）：He <strong>must</strong> be at home because his car is in the driveway.</li><li><strong>建议</strong>（强烈推荐）：You <strong>must</strong> try this new restaurant. The food is amazing.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>must 问句的回答<strong>Must</strong> I go to the park on time? — Yes, you <strong>must</strong>. / No, you <strong>needn&#39;t / don&#39;t have to</strong>.（不，你不必）</p></div><div class="hint-container caution"><p class="hint-container-title">易错</p><p>must 和 have to 的区别（教材 P50） <strong>must</strong>：说话人<strong>主观</strong>看法“一定要”，<strong>无时态和三单变化</strong>；<strong>have to</strong>：强调<strong>客观条件</strong>“不得不做”，<strong>有时态和三单变化</strong>。</p><p>例：He <strong>must</strong> pass the exam, otherwise he <strong>has to</strong> apply for a job.</p></div><h3 id="_4-shall" tabindex="-1"><a class="header-anchor" href="#_4-shall"><span>4. shall</span></a></h3><ol><li>用于<strong>第一人称</strong>（I/we）表将来“将；会”：I <strong>shall</strong> be back soon.</li><li><strong>征求对方意见</strong>（第一、三人称）“……好吗；要不要”：<strong>Shall</strong> I open the window?</li><li>用于<strong>第二、三人称</strong>，表示命令、警告、允诺、威胁、决心：You <strong>shall</strong> not leave this room without permission.（未经允许你不得离开这个房间——命令）</li><li>用于<strong>法律、规则、条款</strong>，表示义务、规定：The applicant <strong>shall</strong> provide all the necessary documents.</li></ol><h3 id="_5-should" tabindex="-1"><a class="header-anchor" href="#_5-should"><span>5. should</span></a></h3><ol><li><strong>建议</strong>（应该）：You <strong>should</strong> eat more vegetables.</li><li><strong>合理推测</strong>（可能）：They <strong>should</strong> be home by now.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>should 和 ought to 的区别ought to 表义务和责任时，比 should <strong>语气重</strong>。</p></div><h3 id="_6-will-would" tabindex="-1"><a class="header-anchor" href="#_6-will-would"><span>6. will / would</span></a></h3><ol><li><strong>意愿</strong>：I <strong>will</strong> never give up.</li><li><strong>请求</strong>：<strong>Will</strong> you pass me the salt?</li><li><strong>习惯</strong>：Boys <strong>will</strong> be boys.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>will 问句回答肯定：Yes, 主语 + will.　否定：No, 主语 + won&#39;t.</p></div><h3 id="_7-dare" tabindex="-1"><a class="header-anchor" href="#_7-dare"><span>7. dare</span></a></h3><ol><li><strong>作情态动词</strong>“敢”（多用于否定句和疑问句）：She <strong>dare not</strong> say what she thinks. / <strong>Dare</strong> you walk in the dark alone?</li><li><strong>作实义动词</strong>“敢”，后面常接 to do：He always <strong>dares to</strong> challenge the authority.　注意：过去式 <strong>dared</strong>；否定式 <strong>daren&#39;t</strong>。</li></ol><h3 id="_8-need" tabindex="-1"><a class="header-anchor" href="#_8-need"><span>8. need</span></a></h3><ol><li><strong>作情态动词</strong>（多用于否定句和疑问句）+ 动词原形：<strong>Need</strong> I say more about the topic?</li><li><strong>作实义动词</strong>：主语是<strong>人</strong>：need <strong>to do</strong>——She <strong>needs to improve</strong> her English.；主语是<strong>物</strong>：need <strong>doing</strong> = need <strong>to be done</strong>——The car <strong>needs repairing</strong>. = The car <strong>needs to be repaired</strong>.</li></ol><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>need 问句回答肯定：Yes, 主语 + must.　否定：No, 主语 + needn&#39;t / don&#39;t have to.</p></div><h3 id="_9-情态动词的虚拟-教材-p50" tabindex="-1"><a class="header-anchor" href="#_9-情态动词的虚拟-教材-p50"><span>9. 情态动词的虚拟（教材 P50）</span></a></h3><p>You <strong>should have come</strong> to the meeting earlier.（你<strong>本应该</strong>早点来开会的——实际没早点来）</p><table><thead><tr><th>结构</th><th>用法</th></tr></thead><tbody><tr><td>could have done</td><td>含有惋惜之情。肯定句：过去<strong>有能力做而未做</strong>；否定句：过去<strong>本不可能做却做了</strong></td></tr><tr><td>would rather have done</td><td>肯定句：当时宁愿做了某事；否定句表示相反的意思。两者都表示“<strong>后悔</strong>”之意</td></tr><tr><td>would like/love to have done</td><td>过去<strong>愿意做但未做成</strong></td></tr></tbody></table><h3 id="_10-情态动词表猜测-教材-p51–54-·-高频考点" tabindex="-1"><a class="header-anchor" href="#_10-情态动词表猜测-教材-p51–54-·-高频考点"><span>10. 情态动词表猜测（教材 P51–54 · 高频考点）</span></a></h3><p><strong>① 对现在状态的推测（+ 动词原形）</strong></p><table><thead><tr><th>情态动词</th><th>结构</th><th>用法及示例</th></tr></thead><tbody><tr><td>must</td><td>must + 动词原形</td><td>肯定句，<strong>非常肯定</strong>地推测现在主语处于某种状态。She <strong>must be</strong> in the classroom now.（她现在一定在教室里）</td></tr><tr><td>can</td><td>can + 原形（疑问句）；can&#39;t + 原形（否定句）</td><td>can 用于疑问句疑问推测；can&#39;t <strong>强烈否定</strong>推测。<strong>Can</strong> she <strong>be</strong> at home?（她会在家吗）She <strong>can&#39;t be</strong> at home.（她不可能在家）</td></tr><tr><td>could</td><td>could + 动词原形</td><td>疑问句和否定句，<strong>语气较弱</strong>。<strong>Could</strong> she <strong>be</strong> a teacher?（她有可能是老师吗）She <strong>couldn&#39;t be</strong> a teacher.（她不太可能是老师）</td></tr><tr><td>may</td><td>may + 动词原形</td><td>肯定/否定句，<strong>较不确定</strong>。Carl <strong>may be</strong> right.（卡尔可能是对的）He <strong>may not be</strong> here.（他可能不在这里）</td></tr><tr><td>might</td><td>might + 动词原形</td><td>肯定/否定句，<strong>语气更弱</strong>。He <strong>might be</strong> a doctor.（他或许是个医生）</td></tr></tbody></table><p><strong>② 对正在发生事情的推测（+ be doing）</strong></p><table><thead><tr><th>情态动词</th><th>结构</th><th>用法及示例</th></tr></thead><tbody><tr><td>must</td><td>must be doing</td><td>肯定句，<strong>极为肯定</strong>推测此刻正在发生。He <strong>must be working</strong> in his office now.（他现在肯定正在办公室工作）</td></tr><tr><td>can</td><td>can&#39;t be doing（否定句）；can...be doing（疑问句）</td><td>can&#39;t <strong>强烈否定</strong>某事此刻正在发生；can...be doing 疑问推测。She <strong>can&#39;t be playing</strong> outside now. It&#39;s too late.（太晚了，她现在不可能在外面玩）<strong>Can</strong> he <strong>be watching</strong> TV at this moment?（他这会儿会正在看电视吗）</td></tr><tr><td>could</td><td>could be doing</td><td>肯定/否定句，<strong>语气稍弱</strong>。They <strong>could be having</strong> a party in the next room.（可能正在隔壁办派对）He <strong>couldn&#39;t be sleeping</strong> because I heard him talking just now.（不可能在睡觉，我刚听到他说话）</td></tr><tr><td>may</td><td>may be doing</td><td>肯定/否定句，<strong>较不确定</strong>。She <strong>may be cooking</strong> dinner in the kitchen.（可能正在厨房做晚餐）It <strong>may not be raining</strong> outside right now.（此刻外面可能没在下雨）</td></tr><tr><td>might</td><td>might be doing</td><td>肯定/否定句，<strong>语气更弱</strong>。He <strong>might be reading</strong> a book in the library.（他或许正在图书馆看书）</td></tr></tbody></table><p><strong>③ 对过去事情的推测（+ have done）</strong></p><table><thead><tr><th>情态动词</th><th>结构</th><th>用法及示例</th></tr></thead><tbody><tr><td>must</td><td>must have done</td><td>肯定句，<strong>非常肯定</strong>地推测过去某事已经发生。You <strong>must have seen</strong> the answers.（你一定已经看到答案了）</td></tr><tr><td>can</td><td>can&#39;t have done（否定句）；can...have done（疑问句）</td><td>can&#39;t have done <strong>强烈否定</strong>推测过去某事未发生；can...have done 疑问推测。He <strong>can&#39;t have gone</strong> to the supermarket.（他不可能去超市了）<strong>Can</strong> he <strong>have married</strong> such a woman?（他怎么可能娶了这样一个女人）</td></tr><tr><td>could</td><td>could have done</td><td>肯定/否定句，<strong>语气较弱</strong>。Someone <strong>could have taken</strong> it away.（可能有人把它拿走了）He <strong>couldn&#39;t have taken</strong> it home.（他不可能把它带回家了）</td></tr><tr><td>may</td><td>may (not) have done</td><td>肯定/否定句，<strong>较不确定</strong>。He <strong>may have gone</strong> to Beijing.（他可能去北京了）</td></tr><tr><td>might</td><td>might (not) have done</td><td>肯定/否定句，<strong>语气更弱</strong>。He <strong>might have gone</strong> to Beijing.（他或许去北京了）</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>猜测可能性排序<strong>must（最大）&gt; should &gt; may &gt; might &gt; could（弱）&gt; can&#39;t（否定推测：不可能）</strong></p></div><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>be 动词后永远不能加动词原形</strong>（be + doing/done/to do 才对）</p></li><li><p><strong>双宾语 to/for 之分</strong>：send/give 类用 to（动作到达对方完成），buy/make 类用 for（对方不参与）</p></li><li><p><strong>must 表推测可能性最大</strong>，且 must 表“必须”时<strong>无时态变化</strong>，“不得不”用 have to（有时态三单变化）</p></li><li><p><strong>may 问句否定回答用 mustn&#39;t（禁止）/ can&#39;t（不允许）</strong>，不用 mayn&#39;t</p></li><li><p><strong>must 问句否定回答用 needn&#39;t / don&#39;t have to</strong>（不必）</p></li><li><p><strong>need/do 双词性</strong>：主语是物 need doing = need to be done（主动形式表被动）</p></li><li><p><strong>can 表推测只用于否定句和疑问句</strong>；肯定句的“可能”用 may/might/could</p></li><li><p><strong>shall 在法律文件中表义务规定</strong>，不是“将”</p></li><li><p>情态动词 + <strong>have done</strong> = 对过去的推测/虚拟，高频考点</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>变否定句：I should run fast. → ____</strong></p><ul><li>A. I don’t run fast.</li><li>B. I should not run fast.</li><li>C. I am not run fast.</li><li>D. I not should run fast.</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（I should not run fast.）</strong> —— 原题为教材 P46 助动词否定句练习（课件未附答案，笔记补充解析）：陈述句中有情态动词 should，直接在其后加 not。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ I don&#39;t run fast. 用了 do 类助动词来构成否定，但原句里有情态动词 should，应该走变法 1，直接在 should 后加 not。干扰点：跳过“句中有没有情态动词或 be”这一步，条件反射地请了 don&#39;t。</li><li>B ✅ 原句中有情态动词 should，否定句变法 1 是直接在其后加 not → I should not run fast。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ I am not run fast. 凭空加进了 be 动词 am，原句本没有 be；而且 be 后永远不能跟动词原形 run。干扰点：把 be 当成万能的否定工具。</li><li>D ❌ I not should run fast. 把 not 放在了情态动词前面。not 必须紧跟情态动词之后，写成 should not。干扰点：语序错误，否定词的位置放反了。</li></ul><p><strong>整句翻译</strong>：把下面的句子变成否定句：我应该跑得快。→ 我不应该跑得快。</p><p><strong>词组</strong>：<code>run fast</code> 跑得快（fast 是副词，修饰 run）</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·do 类助动词详解（教材 P46））：变法 1：陈述句中有情态动词（should/may/can/must/will/might/could）或 be 动词时，直接在其后面加 not：I should run fast. → I should not run fast.</p></details><p><strong>变否定句：I am a student. → ____</strong></p><ul><li>A. I don’t a student.</li><li>B. I am not a student.</li><li>C. I am no a student.</li><li>D. I not am a student.</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（I am not a student.）</strong> —— 原题为教材 P46 助动词否定句练习（笔记补充解析）：句中有 be 动词 am，直接在 be 后加 not。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ I don&#39;t a student. 少了谓语：don&#39;t 后面必须跟动词原形，而 a student 是名词短语，句子没有着落。干扰点：既用错了否定工具（原句有 be），又把谓语动词整个丢了。</li><li>B ✅ 原句的谓语是 be 动词 am，否定走变法 1：直接在 am 后面加 not → I am not a student。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ I am no a student. 把 no 和 a 叠在一起用，两者不能并存：要么 am not a student，要么 am no student。干扰点：混淆了 no 与 not 的用法。</li><li>D ❌ I not am a student. 把 not 放到了 am 前面。be 动词的否定必须写成 be + not。干扰点：否定词位置放反。</li></ul><p><strong>整句翻译</strong>：把下面的句子变成否定句：我是一名学生。→ 我不是一名学生。</p><p><strong>词组</strong>：<code>be 动词的否定</code> 句中有 be 动词时直接在 be 后面加 not（am not / is not / are not）</p><p><strong>对比自测</strong>：做完后对照 quiz:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·do 类助动词详解（教材 P46））：陈述句中有情态动词或 be 动词时，直接在其后面加 not：I am a student. → I am not a student.</p></details><p><strong>My textbook has disappeared. Who ____ have taken it?</strong></p><ul><li>A. should</li><li>B. must</li><li>C. could</li><li>D. would</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（could）</strong> —— 原题为教材 P54 随堂练习（笔记补充解析）：对过去事情的推测用“情态动词 + have done”；疑问句用 could（谁可能拿走了它）。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ should 表推测时是“按理应该”，而且 should have done 是“本应该做而没做”的虚拟用法，不表示对过去的猜测。干扰点：把 should 的“应该”义套到疑问推测上。</li><li>B ❌ must 表推测把握最大，却只用于肯定句；must have done 表示“一定已经……”，不能用来提问。干扰点：只记住 must 推测语气最强，忽略了它不能出现在疑问句中。</li><li>C ✅ 对过去的事情作推测要用“情态动词 + have done”；这是疑问句，说话人并不确定，用语气较弱的 could → Who could have taken it?。来源：课件未附答案，本条为笔记补充解析。</li><li>D ❌ would have done 表示“本来会做（却没做）”，是虚拟语气，不表示对过去事实的推测。干扰点：以为 would 是 will 的过去式就能管过去推测。</li></ul><p><strong>整句翻译</strong>：我的课本不见了。可能是谁把它拿走了呢？</p><p><strong>词组</strong>：<code>have disappeared</code> 不见了、消失了（现在完成时，强调结果）；<code>could have done</code> 对过去事情的可能性推测（语气较弱）</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·对过去事情的推测（教材 P54））：could have done：肯定/否定句，语气较弱。Someone could have taken it away.（可能有人把它拿走了）</p></details><p><strong>Under the regulations, all the passengers ____ remain in their seats until the plane lands safely.</strong></p><ul><li>A. may</li><li>B. shall</li><li>C. could</li><li>D. would</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（shall）</strong> —— 原题为教材 P54 随堂练习（笔记补充解析）：regulations（规章）中表义务、规定，用 shall（对应 shall 用法第 4 条）。（已校对课件原文 lands safety 的笔误）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ may 表“可以、可能”，是允许或推测，而规章条文要表达的是必须遵守的义务。干扰点：把“允许”当成了“规定”。</li><li>B ✅ shall 用于法律、规则、条款时表示义务、规定（对应课件 shall 用法第 4 条），所以规章里用 shall。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ could 表能力或较弱的推测，与规章要求的强制语气不符。干扰点：把推测用法塞进规定性条文。</li><li>D ❌ would 表意愿或过去的将来，也不能表达条文中的义务。干扰点：would 与 shall 都属将来类助动词，容易混用。</li></ul><p><strong>整句翻译</strong>：根据规章，所有乘客应在飞机安全着陆前留在自己的座位上。</p><p><strong>词组</strong>：<code>under the regulations</code> 根据规章制度；<code>remain in one&#39;s seat</code> 留在自己的座位上；<code>land safely</code> 安全着陆</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·shall 用法第 4 条（教材 P54））：用于法律、规则、条款，表示义务、规定：The applicant shall provide all the necessary documents.</p></details><p><strong>The music ____ so wonderful that everyone stopped to listen.</strong></p><ul><li>A. looked</li><li>B. sounded</li><li>C. tasted</li><li>D. smelled</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（sounded）</strong> —— 原题为笔记“课后加餐”。音乐“听起来”美妙，sound 为感官系动词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ looked 是“看起来”，属视觉，与音乐搭配不当——音乐只能靠听来感知。干扰点：五个感官系动词只记住了形式，没管感官通道对不对。</li><li>B ✅ 音乐靠耳朵感知，用感官系动词 sound（听起来）；sound 后接形容词 wonderful 作表语，构成主系表结构。</li><li>C ❌ tasted 是“尝起来”，用于食物；音乐没有味道，搭配不通。干扰点：把味觉动词用到听觉对象上。</li><li>D ❌ smelled 是“闻起来”，用于气味；音乐无法被闻到。干扰点：与 tasted 一样，属于感官通道张冠李戴。</li></ul><p><strong>整句翻译</strong>：这音乐听起来太美妙了，大家都停下来听。</p><p><strong>词组</strong>：<code>sound wonderful</code> 听起来很棒（sound 是感官系动词，后接形容词作表语）；<code>so ... that ...</code> 如此……以至于……；<code>stop to do sth.</code> 停下来去做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·系动词分类与例句（教材 P45））：五感：look, sound, feel, taste, smell——感官：The song sounds beautiful.（听起来真好听）</p></details><p><strong>You ____ finish the work today; tomorrow is also OK.</strong></p><ul><li>A. mustn’t</li><li>B. needn’t</li><li>C. can’t</li><li>D. shouldn’t</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（needn’t）</strong> —— 原题为笔记“课后加餐”。“明天也可以”说明“不必”今天完成，用 needn’t（不必）；mustn’t 是“禁止”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ mustn&#39;t 表示“禁止、不许”，是命令语气；而后半句 tomorrow is also OK 说明只是“不必今天做完”，并不禁止。干扰点：把“不必”与“禁止”混为一谈。</li><li>B ✅ 后半句“明天也可以”说明今天做不做都行，即“不必”，用 needn&#39;t；need 作情态动词多用于否定句和疑问句。</li><li>C ❌ can&#39;t 意为“不能、不可能”，语气更接近不允许，与“明天也可以”的宽松语气不符。干扰点：把“不可以”当成“不必”。</li><li>D ❌ shouldn&#39;t 是“不应该”，属于建议性的否定，不等于“没有必要”。干扰点：没有区分“不应该做”与“不必做”。</li></ul><p><strong>整句翻译</strong>：你今天不必完成这项工作，明天也可以。</p><p><strong>词组</strong>：<code>needn&#39;t</code> 不必（need 作情态动词的否定形式）；<code>mustn&#39;t</code> 禁止、不许</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·must 问句的回答（needn&#39;t））：Must I go to the park on time? — Yes, you must. / No, you needn&#39;t / don&#39;t have to.（不，你不必）</p></details><p><strong>The light in his room is on. He ____ be studying now.</strong></p><ul><li>A. must</li><li>B. might</li><li>C. can</li><li>D. should</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（must）</strong> —— 原题为笔记“课后加餐”。房间灯亮着，非常肯定地推测“一定正在学习”，must be doing；对现在的推测中 must 可能性最大。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 房间灯亮着是强有力的线索，说话人语气非常肯定 → 用把握最大的 must；be studying 是对“此刻正在发生”的推测结构 must be doing。</li><li>B ❌ might 表“或许”，把握较小，与“灯亮着”这一明确线索不匹配。干扰点：只记得 might 也能表推测，没有比较把握大小。</li><li>C ❌ can 表推测只用于否定句和疑问句，这里是要填进肯定句，不能用 can。干扰点：忽略了 can 表推测的使用限制。</li><li>D ❌ should 表推测时是“按理应该”，把握不如 must，也不能从“灯亮着”推出“按理应该在学习”。干扰点：把“应该”当成肯定的推测。</li></ul><p><strong>整句翻译</strong>：他房间里的灯亮着。他现在一定正在学习。</p><p><strong>词组</strong>：<code>must be doing</code> 一定正在做（对此刻正在发生的事作肯定推测）；<code>The light is on.</code> 灯亮着（说明人在房间里的线索）</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·对正在发生事情的推测（教材 P51–54））：must be doing：肯定句，极为肯定推测此刻正在发生。He must be working in his office now.（他现在肯定正在办公室工作）</p></details><p><strong>The sun ____ in the east every day, and we should ____ our hands when we have questions.</strong></p><ul><li>A. rises; raise</li><li>B. raises; rise</li><li>C. rises; rise</li><li>D. raises; raise</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（rises; raise）</strong> —— 原题为笔记“课后加餐”。rise 不及物（太阳自己升起）；raise 及物（举起某物 raise our hands）。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 第一空主语 The sun 自己升起，rise 是不及物动词，第三人称单数用 rises；第二空 raise our hands 里 raise 后跟宾语 our hands，是及物动词。</li><li>B ❌ 两空都反了：raises 是及物动词，后面却缺宾语；rise 是不及物动词，不能带 our hands 这样的宾语。干扰点：把两个词形当成同义可换。</li><li>C ❌ 第二空错了：rise 不及物，不能直接带宾语 our hands，应改成及物动词 raise。干扰点：第一空判断对了就急着收工，没回头看第二空。</li><li>D ❌ 第一空错了：raises 是及物动词，The sun 后面没有宾语，语法站不住；第二空 raise 才对。干扰点：只把第二空判断对了。</li></ul><p><strong>整句翻译</strong>：太阳每天从东方升起，我们有问题时应该举手。</p><p><strong>词组</strong>：<code>rise</code> 升起（不及物动词，后面不跟宾语）；<code>raise</code> 举起、抬高（及物动词，后面必须跟宾语）；<code>raise one&#39;s hand</code> 举起手</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·实义动词 vi./vt. 与易错清单）：少数动词既是 vi. 也是 vt.：He left yesterday.（不及物）／He left Beijing yesterday.（及物）。rise 不及物（太阳自己升起）；raise 及物（举起某物 raise our hands）。</p></details><p><strong>We should ____ quiet in the library to respect others.</strong></p><ul><li>A. keep</li><li>B. stay</li><li>C. remain</li><li>D. All of the above</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（All of the above）</strong> —— 原题为笔记“课后加餐”。keep/stay/remain 都可作系动词表“保持安静”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ keep 确实能作系动词表“保持”（keep quiet），但说它正确就等于排除了同样成立的 stay、remain，答案不完整。干扰点：见到最熟的词就直接选，没有把三个都验证一遍。</li><li>B ❌ stay 能作系动词表“保持”（stay happy），但同样不是唯一答案。干扰点：把单选当成“选最熟的那个”，忽略了选项 D 的存在。</li><li>C ❌ remain 能作系动词表“保持”（remain poor），也不是唯一答案。干扰点：只在三个词之间比较熟悉度，没有回头看“All of the above”。</li><li>D ✅ keep、stay、remain 都可作系动词表“保持”，后接形容词 quiet 作表语，三者都成立，故选 All of the above。</li></ul><p><strong>整句翻译</strong>：在图书馆里我们应该保持安静，以尊重他人。</p><p><strong>词组</strong>：<code>keep / stay / remain + adj.</code> 保持……（三保持系动词后可接形容词作表语）；<code>respect others</code> 尊重他人</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件·系动词分类与口诀（教材 P45））：三保持：keep, stay, remain。保持：He stayed happy after the disease. / She remained poor after the hard work.</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 动词分类：<strong>情 义 助 你 系 鞋 带</strong>（情态、实义、助动词、系动词）</p><p>系动词：<strong>五感（look/sound/feel/taste/smell）、五变（become/get/turn/go/grow/come）、三保持（keep/stay/remain）、两结果（prove/turn out）、一是（be）、一像（seem）</strong></p><p>情态动词用法：<strong>不随主语变 / 后接动词原 / 变否加 not / 变疑要提前</strong></p><p>助动词四大帮手：<strong>do、have、be、will</strong></p><p>must 问句回答：肯定用 must，否定用 <strong>needn&#39;t</strong>；may 问句否定回答用 <strong>mustn&#39;t/can&#39;t</strong></p></div><p>延伸阅读：动词 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,154),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/6/`},{default:i(()=>[...l[5]||=[e(`← 第 6 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/8/`},{default:i(()=>[...l[7]||=[e(`第 8 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};